        assert all(a[k]==b[k] for k in ['video','frame','old_id','raw_id'])
        if (a['scores'][arm]>0)!=(b['scores'][arm+'__parts']>0):changes[arm].append(dict(**{k:a[k] for k in ['video','frame','old_id','raw_id','label']},old=a['scores'][arm],new=b['scores'][arm+'__parts']))
