card['evidence'] += [dict(kind='file',ref='research_partitioned_correspondence_20261109/'+n,claim=t) for n,t in [('summary.json','Все отрицательные допуски'),('decision_changes.json','У FlyVis ни одного изменённого решения'),('audit.json','Независимая проверка180моделей'),('РЕЗУЛЬТАТ.md','Ограниченный отрицательный итог')]]
atomic(path,(json.dumps(cat,ensure_ascii=False,indent=2)+'\n').encode(),before)
path=ROOT/'experiments/system_problems.json';before=path.read_bytes();problems=json.loads(before);problem=next(x for x in problems['problems'] if x['id']=='С2');problem.setdefault('revisions',[]).append(dict(date=now.isoformat(),field='next_check',old=problem['next_check'],reason='Локальные части проверены; новый следующий узел — шкала входов регуляризованной головы.'))
